algorithms.pseudocode:
function PICARD(f, K, x0, tol, max_iters):
    require 0 <= K < 1
    x <- x0
    for n = 1 .. max_iters:
        x_next <- f(x)
        if |x_next - x| <= tol: return (x_next, n)
        x <- x_next
    return (x, max_iters)

function STABILITY_CERTIFICATE(f, g, K, x_f, x_g):
    require 0 <= K < 1
    actual <- |x_f - x_g|
    bound  <- |f(x_g) - g(x_g)| / (1 - K)
    return { actual, bound, valid: actual <= bound }

function SCHEDULE_FACTOR(K_0, ..., K_{n-1}):
    factor <- 1
    for i = 0 .. n-1:
        require K_i >= 0
        factor <- factor * K_i
    return factor
